MultiLanguageSpellData['mx'][340079] = {name = "[q5]Esencia de colmillo de sangre", additional_info = "Poder de talla de runas\n[q2]Tus habilidades que generan p. de combo tienen una probabilidad de infectar al objetivo con Colmillo de sangre, que inflige 0 p. de daño de sangrado durante 6 s y te sana un 50% del daño infligido.\n(Probabilidad de que accione: 30%, 200ms de reutilización)\n[q]Tallado rúnico en: Cabeza, Hombro, Dedo\n[q]Requiere: Pícaro"}
MultiLanguageSpellData['mx'][340080] = {name = "[q5]Polvo de sombras vigorizante", additional_info = "Poder de talla de runas\n[q2]Esfumarse reduce 20 s el tiempo de reutilización restante de tus demás habilidades.\n[q]Tallado rúnico en: Cuello, Pecho\n[q]Fuente: Se compra a cambio de honor al proveedor Zo'kuul. Debes haber desbloqueado Tallado rúnico para comprar este recuerdo.\n[q]Requiere: Pícaro"}
MultiLanguageSpellData['mx'][340081] = {name = "[q5]Ladronzuelo presto", additional_info = "Poder de talla de runas\n[q2]Envenenar también aumenta la probabilidad de golpe crítico de tus venenos un 15%, y sus golpes críticos generan 1 p. de energía.\n[q]Tallado rúnico en: Pies, Espalda\n[q]Requiere: Pícaro (Asesinato)"}
MultiLanguageSpellData['mx'][340082] = {name = "[q5]Espada apocalíptica", additional_info = "Poder de talla de runas\n[q2]Mutilar inflige un 45% más de daño de sangrado durante 8 s.\n\n El daño de Envenenar aumenta un 5% por cada acumulación de sangrado que tengas en el objetivo.\n[q]Tallado rúnico en: Hombro, Manos, Espalda\n[q]Fuente: Botín: Torghast, la Torre de los Condenados. Mort'regar, nivel 3+\n[q]Requiere: Pícaro (Asesinato)"}
MultiLanguageSpellData['mx'][340083] = {name = "[q5]Insignia de Zoldyck", additional_info = "Poder de talla de runas\n[q2]Tus venenos y sangrados infligen un 30% más de daño a los objetivos que tienen menos del 30% de salud.\n[q]Tallado rúnico en: Piernas, Pies\n[q]Fuente: Botín: Torghast, la Torre de los Condenados. Intersticio Despiadado, nivel 3+\n[q]Requiere: Pícaro (Asesinato)"}
MultiLanguageSpellData['mx'][340084] = {name = "[q5]Parche del crepusculante", additional_info = "Poder de talla de runas\n[q2]El tiempo de reutilización restante de Marca mortal se reduce 1 s por cada 30 p. de energía que gastes.\n[q]Tallado rúnico en: Pecho, Dedo\n[q]Requiere: Pícaro (Asesinato)"}
MultiLanguageSpellData['mx'][340085] = {name = "[q5]Varas de mimbre verdes", additional_info = "Poder de talla de runas\n[q2]Entre los ojos tiene un 20% de probabilidad por punto de combo de aumentar un 300% el daño de tu siguiente Disparo de pistola.\n[q]Tallado rúnico en: Cabeza, Cintura\n[q]Requiere: Pícaro (Forajido)"}
MultiLanguageSpellData['mx'][340086] = {name = "[q5]Talismán de sagacidad", additional_info = "Poder de talla de runas\n[q2]Te aprovechas del ritmo natural del combate y tu Golpe siniestro aumenta gradualmente el daño infligido hasta un máximo de 15%. Este efecto máximo durará 12 s antes de desvanecerse y comenzar un nuevo ciclo.\n[q]Tallado rúnico en: Cuello, Muñecas\n[q]Requiere: Pícaro (Forajido)"}
MultiLanguageSpellData['mx'][340087] = {name = "[q5]Celeridad", additional_info = "Poder de talla de runas\n[q2]Subidón de adrenalina aumenta tu daño un 8%, y tienes una probabilidad de obtener el efecto de Subidón de adrenalina durante 3 s mientras Hacer picadillo está activo.\n[q]Tallado rúnico en: Hombro, Dedo\n[q]Requiere: Pícaro (Forajido)"}
MultiLanguageSpellData['mx'][340088] = {name = "[q5]Trabuco oculto", additional_info = "Poder de talla de runas\n[q2]Cuando Golpe siniestro golpea una vez más, hay un 40% de probabilidad de que tu próximo Disparo de pistola se dispare 3 veces más.\n[q]Tallado rúnico en: Muñecas, Manos\n[q]Fuente: Botín: Torghast, la Torre de los Condenados. La Fragua de Almas, nivel 3+\n[q]Requiere: Pícaro (Forajido)"}
