MultiLanguageSpellData['mx'][342666] = {name = "Polilla de Ardenweald ambarina", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El tono naranja brillante de la polilla de Ardenweald ambarina advierte a los depredadores que sería peligroso comerla. Consumir una de estas criaturas provocará un sueño de largos años en el depredador.\"\nBotín:\nSuministros de los Cazadores salvajes\nZona:\nArdenweald"}
MultiLanguageSpellData['mx'][342667] = {name = "Revoloteadora vibrante", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Estas polillas verde menta son muy amistosas. Particularmente, disfrutan de que les cepillen la cabeza vigorosamente. También les gusta la música y la poesía.\"\nVendedor:\nCortinarius\nZona:\nArdenweald"}
MultiLanguageSpellData['mx'][342668] = {name = "Cazador aladesértica", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"En servicio al gran Propósito, los cazadores aladesértica fueron diseñados para cubrir los cielos lejanos de los reinos perdidos de las Tierras de las Sombras.\"\nProfesión:\nSíntesis de protoformas"}
