MultiLanguageSpellData['mx'][346707] = {name = "Expiación del captor", additional_info = "Instante\n[q]Revive una pequeña parte del camino a la expiación de Yevkek, el Esclavizador. Hace que los venthyr enemigos te detecten a mayor distancia y aumenta la reputación que obtienes de los rituales de almas fugitivas en los Salones de Expiación."}
