MultiLanguageSpellData['mx'][353856] = {name = "Salvajezno de Ardenweald", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"A medida que el ánima fluye nuevamente por las distintas arboledas de Ardenweald, más salvajeznos se despiertan y emergen con cuidado de sus madrigueras.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageSpellData['mx'][353857] = {name = "Salvajezno otoñal", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los salvajeznos son criaturas mágicas y benevolentes de Ardenweald que se ven atraídas por las almas puras y fuertes.\"\nPacto:\nNoctifeérico\nVendedora:\nElwyn\nZona:\nArdenweald\nCosto:\n7500"}
MultiLanguageSpellData['mx'][353858] = {name = "Salvajezno invernal", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los salvajeznos sirven como unidades de apoyo en batalla: se encargan de cuidar a sus aliados y disipar los hechizos del enemigo.\"\nPacto:\nNoctifeéricos\nVendedora:\nDuquesa Mynx\nZona:\nKorthia\nCosto:\n1000\nLogro:\nA la ofensiva"}
MultiLanguageSpellData['mx'][353859] = {name = "Salvajezno estival", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Rebelde y testarudo, este salvajezno es leal a muy pocos, pero comparte un vínculo de por vida con ellos.\"\nPacto:\nNoctifeéricos\nBotín:\nSalvajezno fugitivo\nZona:\nKorthia"}
MultiLanguageSpellData['mx'][353860] = {name = "Salvajezno primaveral", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura."}
