MultiLanguageSpellData['mx'][353866] = {name = "Alatumba de obsidiana", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"En los oscurecidos cielos de Revendreth, no puedes ver a estas criaturas hasta que es demasiado tarde.\"\nPacto:\nVenthyr\nVendedor:\nChachi, el Gran artista\nZona:\nRevendreth\nCosto:\n7500"}
