MultiLanguageSpellData['mx'][353872] = {name = "Alatumba de Caída del Pecado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Ahora que el ánima fluye nuevamente en Caída del Pecado, la Piedramadre ha podido imbuir a estos petronato para convertirlos en valiosos aliados para las batallas que se avecinan.\"\nPacto:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['mx'][353873] = {name = "Alatumba pálido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los alatumbas no conocen el miedo y son casi indestructibles. Ideales para un asalto a las Fauces.\"\nPacto:\nVenthyr\nVendedora:\nDuquesa Mynx\nZona:\nKorthia\nCosto:\n1000\nLogro:\nA la ofensiva"}
MultiLanguageSpellData['mx'][353875] = {name = "Aquilón elíseo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Ahora que el ánima fluye nuevamente hacia la Forja Eterna de Bastión, los planes para el aquilón centurión se pueden fabricar una vez más.\"\nPacto:\nKyrian\nZona:\nBastión"}
MultiLanguageSpellData['mx'][353877] = {name = "Aquilón de los Rechazados", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Estos centuriones poderosos, que originalmente desarrollaron los Rechazados con planos robados, están ganando reconocimiento por todas las Tierras de las Sombras.\"\nPacto:\nKyrian\nBotín:\nRajamundos salvaje\nZona:\nKorthia"}
