MultiLanguageSpellData['mx'][353880] = {name = "Aquilón de ascendiente", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El aquilón puede transportar rápidamente aspirantes, auxiliares e incluso ascendidos. Ey, no juzgues, ¡a veces se te cansan las alas!\"\nPacto:\nKyrian\nVendedor:\nAyudante Galos\nZona:\nBastión\nCosto:\n7500"}
