MultiLanguageSpellData['mx'][353929] = {name = "Flagelo de alma en pena", additional_info = "Rango ilimitado\nInstante\n[q]Sylvanas agobia a los objetivos con una aflicción voraz que inflige 1 p. de daño de las sombras por segundo. Este efecto se acumula. Cuando se elimina, genera un charco de sombras en el suelo. Cualquier jugador que toca el charco obtiene Flagelo de alma en pena , lo que consume el charco."}
