MultiLanguageSpellData['mx'][353935] = {name = "Daga de las sombras", additional_info = "Rango ilimitado\nHechizo de 1.5 seg\n[q]Sylvanas lanza una flecha imbuida en terror al jugador, le inflige 47924 p. de daño de las sombras y hasta 111823 p. más de daño de las sombras a todos los demás jugadores. Este daño disminuye según la distancia desde el punto de impacto."}
MultiLanguageSpellData['mx'][353936] = {name = "Té de enfoque del trueno", additional_info = "[q]Ahora Té de enfoque del trueno también puede causar el efecto de repulsión de Relámpago crepitante de jade de inmediato, o hacer que Rodar y Torpedo de chi restituyan una carga cuando los uses y te sanen ([240% of Attack Power]) p. de salud."}
