MultiLanguageSpellData['mx'][354122] = {name = "Esencia succionada", additional_info = "Instante\n[q]Sientes que te invade una sensación general de malestar. Un miasma tangible que pesa sobre tu alma en un mundo oscuro e insensible. Sería necio y, quizá, peligroso seguir con esta decisión. Pobres de los que continúen, pues les espera un final trágico, sin duda. Un final impronunciable, demasiado terrible para considerarlo."}
