MultiLanguageSpellData['mx'][354332] = {name = "Bendición del alma traviesa", additional_info = "Alcance de 50 m\nInstante\nAproximadamente 3 activaciones por minuto\n[q]Te asiste un espíritu travieso, lo que les otorga a tus ataques una probabilidad de desorientar a un enemigo durante 4 s."}
MultiLanguageSpellData['mx'][354333] = {name = "[q5]Placer pecaminoso", additional_info = "Poder de talla de runas\nInstante\n[q2]Consumir [ Arcano : Lanzamiento libre ] [ Fuego : una carga de Explosión de fuego /\n\nEscarcha\nCongelación cerebral ] reduce 4 s del tiempo de reutilización de Espejos de tormento. Si se disipa Espejos de tormento, el tiempo de reutilización se reduce 45 s.\n[q]Tallado rúnico en: Piernas, Pies\n[q]Fuente: Se otorga cuando alcanzas reconocimiento 48 con tu pacto.\n[q]Requiere: Mago"}
MultiLanguageSpellData['mx'][354334] = {name = "¡Enganchado!", additional_info = "Alcance de 300 m\nInstante\n[q]Colagarfio engancha a un jugador con su cola durante 3 s y hace que sangre, lo que inflige 2182004 p. de daño físico cada 3 s durante 9 s."}
