MultiLanguageSpellData['mx'][359222] = {name = "Comida podrida", additional_info = "Alcance de 200 m\nHechizo de 1.5 seg\n[q]Los parroquianos revoltosos arrojan desechos asquerosos que infligen 7273348 p. de daño de naturaleza a los jugadores en un radio de 0 m de la ubicación del impacto."}
