MultiLanguageSpellData['mx'][359229] = {name = "Vombata cuoreluz", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los Iluminados veneran a todas las creaciones de los Primeros, pero para muchos, los vombata de Zereth Mortis son los más queridos. Estas criaturas son fieles bestias de carga y amadas compañeras.\"\nVendedor:\nVilo\nZona:\nZereth Mortis\nLos Iluminados - Exaltado\nCosto:\n5000"}
MultiLanguageSpellData['mx'][359230] = {name = "Huelecristales curioso", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"A la mayoría de los vombata les gusta excavar túneles en la tierra, pero estos rastreadores parecen tener una habilidad única para encontrar cristales enterrados en las profundidades y son capaces de acumular grandes cantidades.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageSpellData['mx'][359231] = {name = "Vombata oscurecido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El esquema para sintetizar a estos vombata oscurecidos parece haber aparecido como una reacción a la invasión de los jurafauces. Los vombata que emergieron se ven diferentes: más oscuros, como los invasores, pero se comportan normalmente.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageSpellData['mx'][359232] = {name = "Vombata ornamentado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los Iluminados consideran que los vombata rojos son criaturas de buena fortuna. Fue un vombata rojo el que estuvo presente cuando llegaron a Zereth Mortis.\"\nProfesión:\nSíntesis de protoformas"}
MultiLanguageSpellData['mx'][359233] = {name = "Lanza", additional_info = "Alcance de 200 m\nHechizo de 1.5 seg\n[q]El ataque principal de Halondrus inflige daño físico a su objetivo actual."}
MultiLanguageSpellData['mx'][359234] = {name = "Rey magma darjonic", additional_info = "Instante\n[q]¡Obliga al líder djaradin local a abandonar su escondite para que puedas derrotarlo y ganar una gran recompensa!"}
MultiLanguageSpellData['mx'][359235] = {name = "Forma de recolección", additional_info = "Hechizo de 6 seg\n[q]Halondrus se inserta sobre una Fisura efimerial , lo que inflige 15664 p. de daño físico a todos los jugadores cada vez que mete una pierna en la arena.\n\n Activa Motor de eternidad ."}
MultiLanguageSpellData['mx'][359236] = {name = "Forma de reubicación", additional_info = "Hechizo de 5.5 seg\n[q]Halondrus recupera su movilidad e inflige 15664 p. de daño físico a todos los jugadores cada vez que saca una pierna de la arena."}
