MultiLanguageSpellData['mx'][359253] = {name = "Conducto de las sombras", additional_info = "Alcance de 30 m\nCanalizado\n[q]El taumaturgo se funde con las sombras para volverse invisible, y luego canaliza para infligir 0 p. de daño de las sombras a un objetivo y sanar 8 % de su salud cada 5.2 s durante hasta que se cancela."}
