MultiLanguageSpellData['mx'][359291] = {name = "Improvisación con cuerno", additional_info = "Alcance de 200 m\n{Instante} {1 seg de reutilización}\n[q]Improvisa con el cuerno para acertar las notas en un radio de 2 m. Cada nota otorga al artista una aplicación de En onda ."}
MultiLanguageSpellData['mx'][359307] = {name = "Mochila de Navarro", additional_info = "Instante\n[q]¡Toma tu mochila favorita y vete!"}
MultiLanguageSpellData['mx'][359313] = {name = "Expulsión cargada", additional_info = "Alcance de 7 m\nHechizo de 1.5 seg\n[q]Inflige daño cósmico al objetivo y daño cósmico adicional cada 1 s durante 6 s."}
MultiLanguageSpellData['mx'][359314] = {name = "Configuración protofórmica manifiesta", additional_info = nil}
MultiLanguageSpellData['mx'][359315] = {name = "Llama del alma", additional_info = "Alcance de 100 m\nInstante\n[q]Aumenta el daño de fuego de los jugadores cercanos un 20% durante 3 min. Este efecto se acumula."}
MultiLanguageSpellData['mx'][359317] = {name = "Wen Lo, el colmillo del río", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La naturaleza de los ríos de Pandaria es impredecible como Wen Lo. Pueden permanecer calmos y nutrir las cosechas o desatar inundaciones terribles. Wen Lo nos recuerda que, para sobrevivir a los desafíos de la vida, es necesario adaptarse.\"\nTienda del juego"}
MultiLanguageSpellData['mx'][359318] = {name = "Tomo de hechizos volador", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Se ha encontrado a este tomo de tamaño descomunal aleteando como loco por todo el salón de las profundidades olvidadas de la biblioteca de Dalaran. Abre este libro de páginas imbuidas de magia arcana y móntate a una aventura mágica.\"\nLogro:\nEl tour de las torres\nCategoría:\nCronoviajes"}
MultiLanguageSpellData['mx'][359319] = {name = "Quest Complete: Daily", additional_info = nil}
MultiLanguageSpellData['mx'][359320] = {name = "Kill Credit: Rare", additional_info = nil}
MultiLanguageSpellData['mx'][359326] = {name = "Portento lúgubre", additional_info = "Rango ilimitado\nInstante\n[q]El sinoescriba Roh-Kalo vincula a varios jugadores con las runas del Telar de los destinos.\n\n Tras 9 s, si un jugador vinculado toca la runa que tiene asignada, el sinoescriba inflige 19968 p. de daño de las sombras a todos los jugadores posados sobre la runa.\n\n Si una runa expira sin que el jugador vinculado esté encima, el sinoescriba inflige 107829 p. de daño de las sombras a todos los jugadores."}
MultiLanguageSpellData['mx'][359333] = {name = "Caldera vacía de sopa de piedra", additional_info = "Hechizo de 3 seg\nComponentes:\nCaldera vacía , Piedra sombreada , Agua de manantial refrescante (5)\nVendedor:\nOlea Manu\nZona:\nZereth Mortis\nCosto:\n25\n\n[q2]Uso: Prepara una caldera de sopa de piedra que estará lista para agregarle ingredientes deliciosos. ¡Complétala para alimentar hasta 35 personas de tu grupo o banda!\n\n Una vez completa, restaura 173077 p. de salud y 138461 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 53 p. de una estadística durante 1 h.\nNecesitas ser de nivel 60"}
MultiLanguageSpellData['mx'][359334] = {name = "Descarga reformante", additional_info = "Alcance de 30 m\nHechizo de 1.5 seg\n[q]Inflige daño cósmico."}
MultiLanguageSpellData['mx'][359335] = {name = "Ventana de construcción: Caldero de sopa de piedra", additional_info = nil}
MultiLanguageSpellData['mx'][359336] = {name = "Preparar caldera de sopa de piedra", additional_info = "Alcance de 5 m\nHechizo de 1 seg\n[q]Prepara una caldera de sopa de piedra que estará lista para agregarle ingredientes deliciosos. ¡Complétala para alimentar hasta 35 personas de tu grupo o banda!\n\n Una vez completa, restaura 173077 p. de salud y 138461 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 53 p. de una estadística durante 1 h."}
MultiLanguageSpellData['mx'][359337] = {name = "Estrella de deconstrucción", additional_info = "Alcance de30\n-[q2]40\nm\nHechizo de 3 seg\n[q]Inflige daño cósmico y daño cósmico adicional cada 5.2 s a todos los enemigos en un radio de 30 m del objetivo."}
