MultiLanguageSpellData['mx'][367950] = {name = "Esperanza del león", additional_info = "Aproximadamente 20 activaciones por minuto\n[q]Tus hechizos tienen una probabilidad de otorgarte Esperanza, lo que aumenta tu intelecto 17 p. durante 12 s. Tienes una mayor probabilidad de obtener Esperanza cuando seleccionas como objetivo a los aliados o enemigos con poca salud."}
MultiLanguageSpellData['mx'][367951] = {name = "Desesperación de los restos", additional_info = "Aproximadamente 20 activaciones por minuto\n[q]Tus hechizos que infligen daño tienen una probabilidad de infligirle Desesperación a tus enemigos, lo que aumenta el efecto de tus enfermedades contra ellos 46 p. durante 12 s. Tienes una mayor probabilidad de infligir Desesperación contra enemigos que tienen más salud."}
MultiLanguageSpellData['mx'][367952] = {name = "Singularidad suprema", additional_info = "[q]Tus hechizos ofensivos generan acumulaciones de Singularidad, lo que otorga 5 p. de versatilidad y velocidad por cada acumulación, hasta un máximo de 20 p.\n\n Al alcanzar 20 p., estas bonificaciones se duplican y persisten durante 20 s. Tras expirar, pierdes todas las acumulaciones y debes esperar 40 s antes de acercarte a la Singularidad de nuevo.\n(100ms de reutilización)"}
