MultiLanguageSpellData['mx'][376910] = {name = "Nutruk de guerra marrón", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los colmillarr de Iskaara desprecian librar una guerra contra quien sea, pero aun así, muchos colmillarr y sus aliados han empuñado la lanza con un nutruk de guerra a su lado.\"\nColmillarr de Iskaara\nReconocimiento:\n30\nVendedor:\nTatto\nUbicación:\nIskaara\nCosto:\n5\n5\n1000"}
