MultiLanguageSpellData['mx'][377441] = {name = "Crescendo de aire", additional_info = "Hechizo de 2 seg\n[q]Dathrea invoca una corriente de aire violenta que fluye hacia el exterior e inflige 35 p. de daño de naturaleza a los jugadores que golpea.\n\n Los jugadores afectados quedan afectados por Tajo persistente ."}
MultiLanguageSpellData['mx'][377442] = {name = "Cubierto de fruta", additional_info = "Alcance de 100 m\nInstante\n[q]Cubierto de fruta del dragón deliciosa."}
