MultiLanguageSpellData['mx'][377445] = {name = "Aura profana", additional_info = "Alcance de 10 m\nInstante\n[q]Todos los enemigos que están en un radio de 8 m reciben un 10% más de daño de tus esbirros."}
MultiLanguageSpellData['mx'][377447] = {name = "Descarga de llamas", additional_info = "Alcance de 50 m\nHechizo de 2 seg\n[q]Lanza una descarga de llamas al objetivo e inflige 0 p. de daño de fuego."}
MultiLanguageSpellData['mx'][377449] = {name = "Decoración de llamas", additional_info = "{Instante} {2 min de reutilización}\n[q]Pisotea el suelo y ordena a las llamas que irradien hacia afuera desde tu posición. Inflige 1690 p. de daño de fuego divididos entre todos los enemigos golpeados y te otorga un escudo de 3155 p. durante 30 s. Después de un tiempo, las llamas regresan, infligen el mismo daño y restauran el escudo.\n\n El daño y la absorción aumentan por cada enemigo golpeado, hasta un máximo de 5 enemigos."}
MultiLanguageSpellData['mx'][377450] = {name = "Globo gélido conjurado", additional_info = nil}
MultiLanguageSpellData['mx'][377451] = {name = "Globo gélido conjurado", additional_info = "Alcance de 40 m\nInstante\n[q]Si tu maná está por encima de un 65%, lanza el Globo gélido a tu objetivo, lo que inflige 3041 p. de daño de escarcha.\n\n Si tu maná está por debajo de un 65%, en su lugar, bebes del Globo gélido para restaurar 562 p. de maná al instante."}
MultiLanguageSpellData['mx'][377452] = {name = "Ícono de susurro encarnado", additional_info = "[q]Sucumbes a los susurros del ícono y te infundes con escarcha , lo que aumenta tu golpe crítico en 57 p.\n\n Luchar junto a aliados que están infundidos con tierra o fuego tiene una probabilidad de otorgarte 16 p. de la estadística de su infusión durante 12 s.\n\n La infusión se basa en tu especialización actual.\n(1.5s de reutilización)"}
MultiLanguageSpellData['mx'][377453] = {name = "Favor de la Devoratormentas", additional_info = "{Instante} {3 min de reutilización}\n[q]Aceptas la tormenta, te conviertes en un elemental de aire primigenio y quedas inmovilizado durante 10 s.\n\n Mientras estás en esta forma, los vientos que te rodean infligen 311 p. de daño de naturaleza por segundo a todos los enemigos en un radio de 10 m. Se intensifica un 10% por segundo hasta que termina la transformación."}
MultiLanguageSpellData['mx'][377454] = {name = "Rubí estruendoso", additional_info = "Aproximadamente 5 activaciones por minuto\n[q]Tus ataques acumulan Fuerza de conmoción lentamente, lo que otorga 3 p. de poder de ataque por acumulación.\n\n Al alcanzar 10 acumulaciones, tus siguientes 3 habilidades cuerpo a cuerpo emiten una ola de choque frente a ti que inflige 903 p. más de daño de naturaleza a todos los enemigos en una línea. Las olas de choque infligen más daño a los enemigos que tienen más salud.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][377455] = {name = "Trampa mortal de sangrehielo", additional_info = "Alcance de 45 m\n{Instante} {2 min de reutilización}\n[q]Inflige 2197 p. de daño de escarcha a tu objetivo y lo encierra junto con los enemigos cercanos en red cristalina durante 15 s. Los enemigos atrapados en redes se ralentizan un 15% y reciben 174 p. de daño de escarcha cuando se golpea a cualquier enemigo enredado.\n\n El daño aumenta por cada enemigo enredado, hasta un máximo de 5. El daño por objetivo se reduce después de golpear a 5 enemigos."}
MultiLanguageSpellData['mx'][377456] = {name = "El arte de las corrientes controladas", additional_info = "[q]Tus golpes críticos tienen una probabilidad de generar Electricidad estática y otorgar un 2% de velocidad de ataque por acumulación. Este efecto puede ocurrir cada 1 s.\n\n Cuando alcanzas 10 acumulaciones, un relámpago te atraviesa y aumenta un 30% tu velocidad de movimiento durante 12 s. Mientras estás bajo ese efecto, tus ataques automáticos aplican descargas a tu objetivo y a 1 enemigo cercano y les infligen 319 p. de daño de naturaleza.\n\n Cuando este efecto expira, se anula la corriente durante 1 min y no puedes generar Electricidad estática.\n(1.5s de reutilización)"}
MultiLanguageSpellData['mx'][377457] = {name = "Tótem total del maestro", additional_info = "[q]Adopta una Postura elemental. Cuando esquivas o paras un ataque exitosamente, desatas un contraataque elemental contra los enemigos que están frente a ti mientras adoptas la siguiente postura.\n\n Este efecto solo puede ocurrir una vez cada 30 segundos.\n(30s de reutilización)"}
MultiLanguageSpellData['mx'][377458] = {name = "Postura elemental: Tierra", additional_info = "Alcance de 100 m\nInstante\n[q]Adopta una Postura elemental. Cuando esquivas o paras un ataque exitosamente, desatas un contraataque elemental contra los enemigos que están frente a ti mientras adoptas la siguiente postura.\n\n Este efecto solo puede ocurrir una vez cada 30 segundos."}
MultiLanguageSpellData['mx'][377459] = {name = "Postura elemental: Fuego", additional_info = "Alcance de 100 m\nInstante\n[q]Adopta una Postura elemental. Cuando esquivas o paras un ataque exitosamente, desatas un contraataque elemental contra los enemigos que están frente a ti mientras adoptas la siguiente postura.\n\n Este efecto solo puede ocurrir una vez cada 30 segundos."}
MultiLanguageSpellData['mx'][377461] = {name = "Postura elemental: Aire", additional_info = "Alcance de 100 m\nInstante\n[q]Adopta una Postura elemental. Cuando esquivas o paras un ataque exitosamente, desatas un contraataque elemental contra los enemigos que están frente a ti mientras adoptas la siguiente postura.\n\n Este efecto solo puede ocurrir una vez cada 30 segundos."}
MultiLanguageSpellData['mx'][377462] = {name = "Promesa de la vigilante del linaje", additional_info = "Alcance de 100 mHechizo de 1 seg 5 seg de reutilización\n[q]Designa a otro jugador para vincularte y te conviertes en su guardián durante 1 h.\n\n Mientras están vinculados, tú y tu aliado obtienen [ 11 * (0.8)] p. de versatilidad y restauran [ 45 * (0.6)] p. de salud por segundo. Si se encuentran a menos de 15 m del otro, estas bonificaciones aumentan.\n\nSolo es válido para especializaciones de sanadores."}
MultiLanguageSpellData['mx'][377463] = {name = "Antorcha ruinosa maníaca", additional_info = "Alcance de 40 mCanalizado (Hechizo de 2 seg) 2 min de reutilización\n[q]Canaliza durante 2 s y desata una salva de llamas furiosas que inflige hasta [ 951 * (8) * (1 + Versatilidad)] p. de daño de fuego a tu objetivo y tiene una probabilidad de golpear a enemigos cercanos por daño adicional.\n\n Cada vez que un jugador aliado muere, este tiempo de reutilización se reduce 90 s."}
MultiLanguageSpellData['mx'][377464] = {name = "Invocación desesperada", additional_info = "Alcance de 45 m\n{Instante} {4 min de reutilización}\n[q]Suelta una peligrosa corriente de relámpagos que inflige 5877 p. de daño de naturaleza a tu objetivo y 31 p. de daño de naturaleza a ti. El daño autoinfligido aumenta con tus acumulaciones de Odio."}
MultiLanguageSpellData['mx'][377465] = {name = "Invocación desesperada", additional_info = "[q]Lanzar hechizos te otorga acumulaciones de Odio que disminuyen 1 s el tiempo de reutilización de este abalorio de forma permanente hasta que el combate termina. Este efecto se acumula hasta 180 veces.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][377466] = {name = "Tormenta rencorosa", additional_info = "[q]Lanzar hechizos y habilidades suma acumulaciones de Rencor. Al llegar a 5 acumulaciones, se dispara hacia tu objetivo actual una Descarga de tormenta rencorosa que inflige [ 86 * (6) * (1 + Versatilidad)] p. de daño de naturaleza durante 3 s.\n\n Cuando expira, la descarga regresa, aumenta el Rencor necesario en 1 y aumenta de forma permanente el daño de Descarga de tormenta rencorosa contra el objetivo hasta que uno de los dos muere.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][377467] = {name = "Carga fulminante", additional_info = "Rango ilimitado\nInstante\n[q]Raszageth carga a los objetivos con electricidad, 3 s. Cuando expira, la carga fulminante inflige 88328 p. de daño de naturaleza a los jugadores que están en el área de impacto y salta hacia el jugador afectado más cercano.\n\n Cada vez que Carga fulminante salta a un jugador nuevo, su radio se reduce y el jugador anterior sufre los efectos de Carga persistente ."}
