MultiLanguageSpellData['mx'][381364] = {name = "Surtido de especias exóticas", additional_info = "Hechizo de 2 seg\nComponentes:\nAlfazaque de lava (2), Ingredientes provechosamente empaquetados\nMaterial de profesión\n[q]\"Un ingrediente común que obtienen originalmente los herboristas. Se puede comprar y vender en la casa de subastas.\""}
MultiLanguageSpellData['mx'][381365] = {name = "Papa doblemente cocida", additional_info = "Hechizo de 2 seg\nComponentes:\nPapa de Ohn'ahra (4), Mezcla tres quesos (2)\nComponentes opcionales:\nÚltimos retoques (#192) , Ingrediente secreto (#193)\n[q]Receta para 4 porciones. El número real de porciones varía según la habilidad en la cocina.\n[q2]Uso: Restaura ( 101250 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes.\nNecesitas ser de nivel 60"}
