MultiLanguageSpellData['mx'][381412] = {name = "Galleta de la fortuna predestinada", additional_info = "Hechizo de 2 seg\nComponentes:\nCarta de la fortuna predestinada , Polvo de cacao thaldrasziano (3), Pastelitos de hojaldre (5), Polvo de gemas sedoso (2)\nComponentes opcionales:\nÚltimos retoques (#192) , Ingrediente secreto (#193)\nBotín:\nCarta de la fortuna predestinada\nReceta:\nSe puede comprar en la casa de subastas\n\n[q2]Uso: Restaura ( 80357 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 76 p. de [Primary Stat] durante 1 h.\n\n ¡Que la fortuna te sonría!\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][381413] = {name = "[q3]Estofado abundante de Yusa", additional_info = "Hechizo de 2 seg\nComponentes:\nDorado de aleta insular , Piraña milmordiscos , Costillas de mamut poderoso , Papa de Ohn'ahra , Surtido de especias exóticas\nComponentes opcionales:\nÚltimos retoques (#192)\n[q]Receta para 2 festines. La cantidad real de festines varía según la habilidad para la cocina.\nDescubrimiento:\nAnciana Yusa\nZona:\nLlanuras de Ohn'ahra\n\n[q3]Estofado abundante de Yusa\n[q2]Uso: Separa una generosa cantidad del estofado abundante de Yusa recién hecho para que compartan todos los jugadores.\n\nRestaura ( 45000 / 5 * 20) p. de salud y ( 60000 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 70 p. de tu estadística secundaria más baja durante 1 h.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][381414] = {name = "Proyección onírica", additional_info = "Alcance de 100 m\nInstante\n[q]Sana ([90% of Spell Power]) p. al instante y 381 p. durante 20 s a todos los aliados en un radio de 12 m, lo que finaliza tu viaje espiritual."}
MultiLanguageSpellData['mx'][381415] = {name = "[q3]Reverencia de Gral", additional_info = "Hechizo de 2 seg\nComponentes:\nSaltador prismático (2), Falda de brúfalo estofado (4), Palitos de pescado sabrosos (6), Mare magnum cerúleo (6), Trozo de croacuerno (6), Pastelito grasoso (3)\nComponentes opcionales:\nÚltimos retoques (#192)\n[q]Receta para 2 festines. La cantidad real de festines varía según la habilidad para la cocina.\nMisión de mundo:\nFestín de la comunidad\nZona:\nEl Trecho Azur\n\n[q3]Gran banquete de los kalu'ak\n[q2]Uso: Prepara un festín colmillarr tradicional durante 3 min del que pueden participar todos los jugadores.\n\nRestaura ( 45000 / 5 * 20) p. de salud y ( 60000 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, quedarás bien alimentado y obtendrás 76 p. de tu estadística principal durante 1 h.\nNecesitas ser de nivel 70"}
