MultiLanguageSpellData['mx'][385633] = {name = "Auras del resuelto", additional_info = "[q0]Talento\n[q]Aprendes Aura de concentración, Aura de devoción y Aura de cruzado:\n\nAura de concentración :\nLos efectos de interrupción y silencio sobre los miembros del grupo o banda que están en un radio de 40 m duran un 30% menos.\n\n Aura de devoción :\nLa devoción del taumaturgo potencia a los miembros de la banda y del grupo que están en un radio de 40 m y reduce un 3% el daño recibido.\n\n Aura de cruzado :\nAumenta un 20% la velocidad de montura de todos los miembros del grupo o banda en un radio de 40 m."}
MultiLanguageSpellData['mx'][385634] = {name = "Inconsciente", additional_info = "Alcance de 100 m\nInstante\n[q]Maruuk blande su arma y genera una ráfaga de viento violenta que inflige 15 p. de daño de naturaleza a los jugadores objetivo y los repele.\n\n También aplica Inconsciente a los jugadores objetivo durante 6 s."}
MultiLanguageSpellData['mx'][385635] = {name = "Cámara de la catalogadora", additional_info = "Alcance de 100 m\nInstante\n[q]Te permite catalogar la fauna cercana y los fenómenos naturales durante un paseo relajante."}
