MultiLanguageSpellData['mx'][385638] = {name = "Fragmentos filosos", additional_info = "Alcance de 100 m\nInstante\n[q]Después de obtener Arremetida mortal, tu siguiente Disparo mortal inflige un 75% más de daño y desgarra a un máximo de 5 objetivos cercanos a tu objetivo de Disparo mortal , lo que inflige un 35% del daño infligido por Disparo mortal durante 6 s."}
MultiLanguageSpellData['mx'][385639] = {name = "Auras de venganza veloz", additional_info = "[q]Aprendes Aura de reprensión y Aura de cruzado:\n\n Aura de reprensión :\nCuando un miembro de grupo o banda en un radio de 40 m recibe más del 30% de su salud como daño de un solo golpe, cada miembro obtiene un 5% más de daño y sanación, que se reduce a lo largo de 30 s. Este efecto no puede ocurrir en un período de 30 s de la aplicación del aura.\n\n Aura de cruzado :\nAumenta un 20% la velocidad de montura de todos los miembros del grupo o banda en un radio de 40 m."}
