MultiLanguageSpellData['mx'][385968] = {name = "Invocar S.A.L.V.A.D.O.R.", additional_info = "Alcance de 10 mHechizo de 6 seg 5 min de reutilización\n[q]Coloca un ensamblaje mecánico aliado en el suelo cercano que ofrecerá apoyo moral mientras tus compañeros caen a tu alrededor. Resucitará a todos los miembros del grupo o banda en un radio razonable después de que el combate termine. El tiempo de lanzamiento se reduce según la calidad.\n\n No funciona con jugadores que tengan un nivel superior a 70, que hayan enfurecido al robot o cuyos espíritus hayan sido liberados."}
MultiLanguageSpellData['mx'][385969] = {name = "Invocar S.A.L.V.A.D.O.R.", additional_info = "Alcance de 10 mHechizo de 2 seg 5 min de reutilización\n[q]Coloca un ensamblaje mecánico aliado en el suelo cercano que ofrecerá apoyo moral mientras tus compañeros caen a tu alrededor. Resucitará a todos los miembros del grupo o banda en un radio razonable después de que el combate termine. El tiempo de lanzamiento se reduce según la calidad.\n\n No funciona con jugadores que tengan un nivel superior a 70, que hayan enfurecido al robot o cuyos espíritus hayan sido liberados."}
MultiLanguageSpellData['mx'][385970] = {name = "Orbe arcano", additional_info = "Alcance de 100 m\nInstante\n[q]El profesor invoca orbes encantados del libro mágico que infligen 7273348 p. de daño arcano en un radio de 3 m del impacto y comienzan a gravitar hacia Vexamus.\n\n Si Vexamus absorbe un orbe, el elemental obtendrá 20 p. de energía e infligirá 2917001 p. de daño arcano a todos los jugadores. Si un jugador absorbe un orbe, sufrirá 2431238 p. de daño arcano."}
MultiLanguageSpellData['mx'][385971] = {name = "Orbes arcanos", additional_info = "Rango ilimitado\nInstante\n[q]El profesor invoca orbes encantados del libro mágico que infligen 7273348 p. de daño arcano en un radio de 3 m del impacto y comienzan a gravitar hacia Vexamus.\n\n Si Vexamus absorbe un orbe, el elemental obtendrá 20 p. de energía e infligirá 2917001 p. de daño arcano a todos los jugadores. Si un jugador absorbe un orbe, sufrirá 2431238 p. de daño arcano."}
MultiLanguageSpellData['mx'][385972] = {name = "[q2]Infusión: Escarcha", additional_info = "Hechizo de 2 seg\nComponentes:\nCarnada para criatura esquiva , Escarcha inquieta (2)\nEspecialización:\nFabricante de cebos - Infusión elemental\n\n[q2]Carnada para criatura infundida con escarcha\nSe liga al recogerlo\n[q2]Uso: Coloca la carnada, y al poco tiempo atrae a cualquier criatura esquiva. ¿Quién sabe qué puede aparecer?\n\n Reduce el tiempo de reutilización de carnada para criatura esquiva mediante el desuello de criaturas en las Islas Dragón.\n\n Solo se puede usar en exteriores de las Islas Dragón.\nNecesitas ser de nivel 10\n[q]\"Una carnada muy tentadora que hace que las criaturas esquivas salgan de su escondite. Infundida con la esencia elemental de escarcha.\""}
