MultiLanguageSpellData['mx'][387623] = {name = "Devastación eléctrica", additional_info = "Alcance de 300 m\nInstante\n[q]Raszageth ataca a lo largo de la plataforma y exhala relámpagos en una línea mientras se mueve. Inflige 1766570 p. de daño de naturaleza a los jugadores que están en el área de impacto."}
