MultiLanguageSpellData['mx'][391403] = {name = "Tortura mental: demencia", additional_info = "Alcance de 40 m\nCanalizado (Hechizo de 1.5 seg)\n[q]Asalta la mente del objetivo con energía de las sombras, lo que le inflige ([598.868% of Spell Power]) p. de daño de las sombras durante 1.5 s y reduce un 70% su velocidad de movimiento.\n\nGenera 8 p. de demencia mientras dura."}
MultiLanguageSpellData['mx'][391404] = {name = "Cubierto de descomposición", additional_info = "Instante\n[q]Aflige al herborista con una plaga terrible. Los saltos aceleran el proceso curativo, pero no se siente nada bien."}
MultiLanguageSpellData['mx'][391406] = {name = "Hochenblume", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Hochenblume es la hierba más común de las Islas Dragón. Puede encontrarse casi en cualquier terreno y crece donde sea propicio.\nProfesión:\nHerboristería (1)"}
MultiLanguageSpellData['mx'][391407] = {name = "¡Fallo!", additional_info = nil}
MultiLanguageSpellData['mx'][391409] = {name = "Diseño de Aldrachi", additional_info = "[q0]Talento\n[q]Aumenta un 3% tu probabilidad de parar."}
MultiLanguageSpellData['mx'][391410] = {name = "Invocar elemental de relámpagos", additional_info = nil}
MultiLanguageSpellData['mx'][391412] = {name = "Armonía de fuego de jade", additional_info = "[q0]Talento\n[q]Los enemigos y aliados impactados por Pisotón de fuego de jade quedan afectados por Marca de fuego de jade, lo que aumenta un 6% el daño que les infliges y la sanación que les realizas durante 10 s."}
MultiLanguageSpellData['mx'][391414] = {name = "Yugo del mar", additional_info = "Alcance de 8 m\nHechizo de 3 seg\n[q]Inflige 80 p. de daño de naturaleza a los enemigos en un radio de 15 m.\n\n Inmobiliza a todos los enemigos en un radio de 15 m del taumaturgo durante 5 s."}
MultiLanguageSpellData['mx'][391415] = {name = "Hochenblume exuberante", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Hochenblume es la hierba más común de las Islas Dragón. Puede encontrarse casi en cualquier terreno y crece donde sea propicio.\n\n Algunas hierbas crecen particularmente bien y proliferan por diversas razones, independientemente del clima o la ubicación. Los herboristas que encuentran estos nodos inusuales pueden conseguir materiales útiles adicionales."}
MultiLanguageSpellData['mx'][391417] = {name = "Movimiento del océano", additional_info = "Alcance de 50 m\nHechizo de 3 seg\n[q]Invoca una ola de las profundidades del mar.\n\n spelldesc"}
MultiLanguageSpellData['mx'][391419] = {name = "Congelamiento", additional_info = "Instante\n[q]Después de 6 s, si el jugador no está a 10 m de otros 2 jugadores, queda $spellname391446."}
MultiLanguageSpellData['mx'][391420] = {name = "Loreweaver's Shield TBD", additional_info = nil}
MultiLanguageSpellData['mx'][391421] = {name = "Sanando", additional_info = "Instante\n[q]Sanando por los efectos del fluido fluorescente."}
