MultiLanguageSpellData['mx'][391424] = {name = "Explosión dracónica", additional_info = "Alcance de 300 m\nInstante\n[q]Inflige daño de escarcha a los objetivos golpeados."}
MultiLanguageSpellData['mx'][391425] = {name = "Tempestad frígida", additional_info = "Rango ilimitado\nHechizo de 2.5 seg\n[q]El aire se convierte en hielo, reduce la temperatura drásticamente y requiere que los jugadores permanezcan a 10 m de al menos otros 2 jugadores para evitar Congelación total ."}
MultiLanguageSpellData['mx'][391426] = {name = "Movimiento del océano", additional_info = "Alcance de 1000 m\nInstante\n[q]Inflige 75 p. de daño de naturaleza a un enemigo.\n\n Reduce un 30% la velocidad de movimiento del objetivo durante 5 s.\n\n Repele a un enemigo."}
MultiLanguageSpellData['mx'][391427] = {name = "Vapor de caldero", additional_info = nil}
MultiLanguageSpellData['mx'][391428] = {name = "Veneno", additional_info = nil}
MultiLanguageSpellData['mx'][391429] = {name = "Carne de cañón para la llama", additional_info = "[q]Visión espectral tiene un tiempo de reutilización de 30 s y ahora revela a un demonio condenado durante 25 s. [ Venganza : Devastación vil /\n\nCaos\nHaz ocular ] y Lanzar guja infligen daño letal al demonio y le otorgan un 20% más de daño durante 15 s.\n\n Al morir, el demonio explota, inflige ([192.5% of Attack Power]) p. de daño de las sombras a los enemigos cercanos y te sana por un 20% de tu salud máxima. La explosión inflige menos daño cuando golpea a más de 5 objetivos."}
MultiLanguageSpellData['mx'][391430] = {name = "Carne de cañón para la llama", additional_info = "{Instante} {2 min de reutilización}\n[q]Tus habilidades que infligen daño tienen una probabilidad de invocar un demonio del Teatro del Dolor durante 25 s. Lanzar guja inflige daño letal al demonio, que explota al morir e inflige ([192.5% of Attack Power]) p. de daño de las sombras a los enemigos cercanos y te sana un 20% de tu salud máxima. La explosión inflige menos daño después de afectar a 5 objetivos."}
MultiLanguageSpellData['mx'][391431] = {name = "Hochenblume ventobarrida", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Hochenblume es la hierba más común de las Islas Dragón. Puede encontrarse casi en cualquier terreno y crece donde sea propicio.\n\n Las hierbas que crecen en lo alto o en regiones particularmente ventosas, como las Llanuras de Ohn'ahra, pueden absorber el poder elemental del aire. Poderosas ráfagas de viento se desatan cuando se recolectan estas hierbas, lo que derriba al herborista. Sin embargo, es una forma eficaz de encontrar aire inquieto.\n\n Los herboristas especializados en hierbas ventobarridas obtienen el siguiente efecto al recolectar:\n\n Impulso del viento :\nCuando caigas a una distancia mayor a 40 m, una poderosa ráfaga de viento ralentizará tu descenso."}
MultiLanguageSpellData['mx'][391441] = {name = "Saxifraga", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]La saxifraga es una hierba resistente que crece en una diversidad de lugares. Si bien generalmente puede encontrarse en regiones escarpadas como montañas o riscos, también se ve en llanuras y, en menor medida, en regiones volcánicas."}
MultiLanguageSpellData['mx'][391444] = {name = "Amapola de burbujas", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]La amapola de burbujas es una hierba delicada que crece en ubicaciones acuáticas de las Islas Dragón. Crece a lo largo de ríos y costas, e incluso dentro de cuevas húmedas.\n\n A pesar de su apariencia única, la amapola de burbujas no es particularmente útil. En realidad, el verdadero valor yace en el orbe fúngico acuoso que se forma en su base."}
MultiLanguageSpellData['mx'][391445] = {name = "Ira del mar", additional_info = "Alcance de 1000 m\nInstante\n[q]Inflige 75 p. de daño de naturaleza a un enemigo.\n\n Reduce un 30% la velocidad de movimiento del objetivo durante 5 s.\n\n Repele a un enemigo."}
MultiLanguageSpellData['mx'][391446] = {name = "Congelación total", additional_info = "Rango ilimitado\nInstante\n[q]El frío incapacita al jugador y le inflige 52997 p. de daño de escarcha cada 1 s durante 10 s. Este efecto no se puede mitigar ni evitar."}
MultiLanguageSpellData['mx'][391447] = {name = "Crispacorteza", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]La crispacorteza es una hierba oriunda de las Islas Dragón. Se halla en terrenos con abundancia de árboles y follaje."}
MultiLanguageSpellData['mx'][391449] = {name = "Ira del mar", additional_info = "Canalizado (Hechizo de 32 seg)\n[q]Invoca una olas de agua de océano que infligen 75 p. de daño de naturaleza y ralentizan un 30% a los objetivos."}
MultiLanguageSpellData['mx'][391450] = {name = "Vacío oscuro", additional_info = "Instante\n[q]Libera una explosión de energía oscura alrededor de tu objetivo que inflige ([74.8% of Spell Power]) p. de daño de las sombras y aplica Palabra de las sombras: dolor a tu objetivo y a 15 enemigos cercanos.\n\nGenera 15 p. de demencia."}
