MultiLanguageSpellData['mx'][391453] = {name = "Limpiapaladares", additional_info = "Instante\n[q]Purga agresivamente tu mente, cuerpo y espíritu de... lo que SEA que haya sido eso."}
MultiLanguageSpellData['mx'][391454] = {name = "Explosión dracónica", additional_info = "Alcance de 300 m\nInstante\n[q]Inflige daño de naturaleza a los objetivos golpeados."}
MultiLanguageSpellData['mx'][391457] = {name = "Potenciación de lava", additional_info = "Instante\n[q]Colmimagma se fortalece mientras se para sobre la lava, lo que aumenta un 25% todo el daño que inflige."}
MultiLanguageSpellData['mx'][391458] = {name = "Suelo sanguíneo", additional_info = "[q0]Talento\n[q]Infliges un 6% más de daño y recibes un 5% más de sanación mientras estás dentro de tu Muerte y descomposición."}
MultiLanguageSpellData['mx'][391459] = {name = "Suelo sanguíneo", additional_info = "Instante\n[q]Infliges un 6% más de daño y recibes un 5% más de sanación mientras estás dentro de tu Muerte y descomposición."}
MultiLanguageSpellData['mx'][391460] = {name = "Hochenblume gélida", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Hochenblume es la hierba más común de las Islas Dragón. Puede encontrarse casi en cualquier terreno y crece donde sea propicio.\n\n Cuando se exponen a climas más fríos o se encuentran cerca de fuentes de agua, pueden infundirse con escarcha elemental. Si reúnes estas hierbas, el suelo se cubre de hielo fino, pero el herborista recibe escarcha inquieta como recompensa por sus esfuerzos.\n\n Los herboristas especializados en hierbas Gélidas obtendrán el siguiente efecto al recolectar:\n\n Pétalos gélidos :\nTe envuelves en una nube de escarcha que congela momentáneamente a cualquier enemigo que se te acerca demasiado."}
MultiLanguageSpellData['mx'][391461] = {name = "Cristal ligeramente glacial", additional_info = nil}
MultiLanguageSpellData['mx'][391463] = {name = "Cubierto de descomposición", additional_info = "Instante\n[q]No te sientes muy bien, ¡pero estás mejorando! La velocidad de movimiento y todas las estadísticas se reducen, pero solo un poco."}
MultiLanguageSpellData['mx'][391470] = {name = "Golpe destrozador", additional_info = "Alcance de 10 mHechizo de 2 seg 12 seg de reutilización\n[q]Inflige 125 p. de daño de fuego a un enemigo y elimina 20 efecto mágico beneficioso."}
MultiLanguageSpellData['mx'][391471] = {name = "Esporas purificadoras", additional_info = "Instante\n[q]Envuelve a los jugadores en un radio de 40 m con una nube de Esporas purificadoras que curan una aplicación de un efecto de veneno o enfermedad cada 15 s durante 30 min."}
MultiLanguageSpellData['mx'][391472] = {name = "Acariciando", additional_info = "Alcance de 3 m\nHechizo de 1.5 seg\n[q]¡Acaricia a una criatura linda!"}
