MultiLanguageSpellData['mx'][391477] = {name = "Coagulopatía", additional_info = "[q0]Talento\n[q]Los enemigos afectados por Peste de sangre reciben un 5% más de daño de ti y Golpe letal aumenta el daño de tu Peste de sangre un 25% durante 12 s. Puede acumularse 5 veces."}
MultiLanguageSpellData['mx'][391479] = {name = "Inferno enfurecido", additional_info = nil}
MultiLanguageSpellData['mx'][391481] = {name = "Coagulopatía", additional_info = "Alcance de 100 m\nInstante\n[q]Los enemigos afectados por Peste de sangre reciben un 5% más de daño de ti y Golpe letal aumenta el daño de tu Peste de sangre un 25% durante 12 s. Puede acumularse 5 veces."}
