MultiLanguageSpellData['mx'][391589] = {name = "Costillar al carbón", additional_info = "Instante\n[q]Costillas asadas sobre un colchón de hierba ancla, polen de sirena y carbón vorquin fresco. ¡Con el primer bocado, su intenso sabor corre por tus venas! Aumenta el aguante un 20% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón."}
