MultiLanguageSpellData['mx'][392996] = {name = "Champiñón salvaje", additional_info = "Alcance de 40 m\nInstante\n[q]Crece un champiñón mágico en la ubicación del enemigo objetivo. Después de 1 s, el champiñón explota, inflige ([254.4% of Spell Power]) p. de daño de naturaleza y, luego, ([143.5% of Spell Power]) p. de daño de naturaleza adicional durante 10 s. Los objetivos afectados se ralentizan un 50%.\n\n Genera hasta 20 p. de poder astral según la cantidad de objetivos que golpea."}
MultiLanguageSpellData['mx'][392997] = {name = "Sangre ígnea volátil", additional_info = "Alcance de 100 m\nInstante\n[q]Aura de inmolación genera 5-10 p. de furia cuando inflige daño crítico.\n\n Este efecto solo puede ocurrir una vez cada 1 s."}
