MultiLanguageSpellData['mx'][393057] = {name = "Energía de chi", additional_info = "Instante\n[q]Cada vez que infliges daño con Puños de furia, obtienes una acumulación de energía de chi hasta un máximo de 30 acumulaciones.\n\n Usar Patada giratoria de la grulla hará que la energía detone en una Explosión de chi que inflige ([65% of Attack Power]) p. de daño a todos los enemigos en un radio de 8 m. El daño aumenta un 5% por cada acumulación de energía de chi."}
MultiLanguageSpellData['mx'][393058] = {name = "Lazo de Xuen", additional_info = "Instante\n[q]El daño de Invocar a Xuen, el Tigre Blanco, aumenta un 30% y su tiempo de reutilización se reduce 30 s."}
MultiLanguageSpellData['mx'][393059] = {name = "Piraña milmordiscos", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Las pirañas milmordiscos son peces agresivos de agua dulce que devoran todo a su paso.\n\n Puedes encontrar sus cardúmenes principalmente en lagos grandes y sistemas fluviales de las Islas Dragón.\n\n Se concentran en lugares como las Llanuras de Ohn'ahra y las Costas del Despertar."}
MultiLanguageSpellData['mx'][393060] = {name = "Pez espinoso cerúleo", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los peces espinosos cerúleos son robustos y tienen muchas espinas filosas.\n\n Sus cardúmenes de agua salada pueden encontrarse principalmente en el océano y otros cuerpos de agua que llegan a él.\n\n Se encuentran sobre todo en las cabeceras de los ríos de las Costas del Despertar."}
MultiLanguageSpellData['mx'][393061] = {name = "Pez dragón alerón", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los peces dragón alerón se deslizan por el suelo oceánico y se impulsan hacia arriba cuando sienten que hay un delicioso bocadillo.\n\n Estos cardúmenes de agua salada pueden encontrarse principalmente en el océano y otros cuerpos de agua que llegan a él.\n\n Se encuentran particularmente en Iskaara, en el Trecho Azur."}
MultiLanguageSpellData['mx'][393062] = {name = "Cabeza dracónica temporal", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Las cabezas dracónicas temporales son peces peculiares cuyas escamas parecen moverse hacia adelante y hacia atrás a cada segundo. ¡Mantén los dedos lejos de su filosa trompa!\n\n Estos cardúmenes de agua dulce pueden encontrarse principalmente en los lagos grandes y los sistemas fluviales de las Islas Dragón.\n\n Se encuentran sobre todo en el Remanso Uktulut, en las Costas del Despertar."}
MultiLanguageSpellData['mx'][393063] = {name = "Macarela panzaescamosa", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Las macarelas panzaescamosa son peces muy comunes en las Islas Dragón. Se pueden atrapar con facilidad en todos los cuerpos de agua.\n\n Volver a arrojar al agua las macarelas panzaescamosa que no se utilizan es una práctica de rutina que ejercen hasta los pescadores más experimentados."}
MultiLanguageSpellData['mx'][393064] = {name = "Dorado de aleta insular", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los dorados de aleta insular son peces esquivos cuyas aletas, se dice, tienen la forma de las Islas Dragón.\n\nPueden encontrarse en todos los cuerpos de agua de las Islas."}
MultiLanguageSpellData['mx'][393065] = {name = "Tesoros resplandecientes", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los tesoros resplandecientes pueden aparecer en todos los cuerpos de agua de las Islas Dragón. Contienen tesoros ocultos y son la búsqueda de cualquier pescador.\n\nPescarlos aumenta significativamente tu probabilidad de obtener tesoros raros."}
MultiLanguageSpellData['mx'][393066] = {name = "Atún escarchaleta", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]El atún escarchaleta es un pez grande y carnoso envuelto en una fina capa de hielo que lo protege. Su gruesa capa de grasa protege sus órganos vitales de las temperaturas heladas.\n\n Puedes encontrar estos bancos de peces principalmente en los climas gélidos de las Islas Dragón.\n\n Los colmillarr de Iskaara son expertos en atrapar este tipo especial de peces."}
MultiLanguageSpellData['mx'][393067] = {name = "Trillador de magma", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los trilladores de magma son peces musculosos que tienen una dura coraza exterior compuesta de diversos minerales.\n\n Puedes encontrar estos charcos en climas particularmente cálidos de las Islas Dragón.\n\n Los colmillarr de Iskaara son expertos en atrapar estos tipos de peces."}
MultiLanguageSpellData['mx'][393068] = {name = "Saltador prismático", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los saltadores prismáticos son peces cubiertos de escamas iridiscentes, bastante curiosos y ágiles.\n\n A estos peces les encanta saltar fuera del agua y puedes encontrarlos en algunos de los puntos más altos de las Islas Dragón.\n\n Los colmillarr de Iskaara son expertos en atrapar estos tipos de peces."}
MultiLanguageSpellData['mx'][393070] = {name = "New Class Order", additional_info = nil}
