MultiLanguageSpellData['mx'][393073] = {name = "Mejorar equipo JcJ", additional_info = "Hechizo de 3 seg\n[q]Mejora al siguiente rango una pieza de equipamiento de la temporada 1 de Dragonflight obtenida con honor o conquista.\n\n No se puede mejorar un objeto a un rango mayor que el que te permitiría tu rango más alto de JcJ puntuado."}
MultiLanguageSpellData['mx'][393075] = {name = "Medalla de honor", additional_info = "Hechizo de 1.5 seg\n[q]Reflexionas sobre tus victorias pasadas y obtienes 150 p. de honor.\n\n Debe usarse durante la temporada 3 de Dragonflight."}
