MultiLanguageSpellData['mx'][396162] = {name = "Khaz'gorita", additional_info = "Alcance de 5 m\nHechizo de 5.3 seg\n[q]Los días en que la khaz'gorita emergía de la superficie de las Islas Dragón son cosa del pasado. Los mineros que buscan esta mena poco común solo pueden depender de los rastros que descubren cuando extraen otros metales.\nProfesión:\nMinería (1)"}
MultiLanguageSpellData['mx'][396166] = {name = "Furia de Xuen", additional_info = "[q0]Talento\n[q]Tus Golpes de combo otorgan una probabilidad acumulativa de un 1% de que tu siguiente Puños de furia otorgue un 3% de golpe crítico, celeridad y maestría e invoque a Xuen, el Tigre Blanco, durante 10 s.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][396167] = {name = "Furia de Xuen", additional_info = "Alcance de 100 m\nInstante\n[q]Tus Golpes de combo otorgan una probabilidad acumulativa de un 1% de que tu siguiente Puños de furia otorgue un 3% de golpe crítico, celeridad y maestría e invoque a Xuen, el Tigre Blanco, durante 10 s."}
