MultiLanguageSpellData['mx'][397853] = {name = "[q3]Esencia de forja de acero impresionante", additional_info = "Hechizo de 3.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nLingote de acero puro (100), Sangre salvaje (25), Mena de hierro genuino (20)\nVendedor:\nNonn Trinquetres\nZona:\nLanza de Guerra\nCosto:\n5\n\nVendedor:\nRoyce Barbagrande\nZona:\nEscudo de Tormenta\nCosto:\n5\n\n[q3]Esencia de forja de acero impresionante\nSe liga al recogerlo\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Altera la apariencia de un arma fabricada mediante la herrería de Draenor para que sea más impresionante.\n[q]Puede usarse con: Armas de herrería de Draenor."}
MultiLanguageSpellData['mx'][397855] = {name = "[q4]Esencia de forja de acero notable", additional_info = "Hechizo de 3.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nLingote de acero puro (125), Peste vil (35), Mena de hierro genuino (20)\nVendedor:\nNonn Trinquetres\nZona:\nLanza de Guerra\nCosto:\n5\n\nVendedor:\nRoyce Barbagrande\nZona:\nEscudo de Tormenta\nCosto:\n5\n\n[q4]Esencia de forja de acero notable\nSe liga al recogerlo\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Altera la apariencia de un arma fabricada mediante la herrería de Draenor para que sea verdaderamente notable.\n[q]Puede usarse con: Armas de herrería de Draenor."}
MultiLanguageSpellData['mx'][397856] = {name = "[q3]Esencia de acero puro impresionante", additional_info = "Hechizo de 2.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nLingote de acero puro (50), Sangre salvaje (15), Mena de Roca Negra (20)\nVendedor:\nNonn Trinquetres\nZona:\nLanza de Guerra\nCosto:\n5\n\nVendedor:\nRoyce Barbagrande\nZona:\nEscudo de Tormenta\nCosto:\n5\n\n[q3]Esencia de acero puro impresionante\nSe liga al recogerlo\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Altera la apariencia de las armaduras fabricadas mediante la herrería de Draenor para que sean más impresionantes.\n[q]Puede usarse con: Armaduras de herrería de Draenor."}
